<?php
/** Filterable generated WordPress content history. @package AIContentStudio */
if(!defined('ABSPATH')){exit;}
final class AICS_Content_History_Page{
	private const AJAX_ACTION='aics_content_history';private const NONCE='aics_content_history_nonce';
	public static function register():void{add_action('wp_ajax_'.self::AJAX_ACTION,array(self::class,'ajax'));}
	public static function render():void{self::permission();$service=new AICS_Content_History_Query_Service();$filters=$service->normalize($_GET);$result=$service->query($filters);$authors=$service->authors();?><div class="wrap aics-admin-wrap aics-content-history-page" id="aics-content-history" data-ajax-action="<?php echo esc_attr(self::AJAX_ACTION);?>"><header class="aics-page-header"><h1 class="aics-page-title"><?php esc_html_e('Content History','ai-content-studio');?></h1><p class="aics-page-description"><?php esc_html_e('Search and manage WordPress posts created by AI Content Studio. Temporary articles that were never converted into posts are excluded.','ai-content-studio');?></p></header><?php self::toolbar($filters,$authors);self::tabs($filters);?><div class="aics-history-live" aria-live="polite"></div><div class="aics-history-results" aria-busy="false"><?php self::results($result);?></div></div><?php }
	public static function ajax():void{self::permission();check_ajax_referer(self::AJAX_ACTION,self::NONCE);$result=(new AICS_Content_History_Query_Service())->query($_POST);ob_start();self::results($result);$html=ob_get_clean();wp_send_json_success(array('html'=>$html,'summary'=>array('total'=>$result['total'],'page'=>$result['page'],'pages'=>$result['pages']),'filters'=>$result['filters'],'notice'=>$result['error']?:null));}
	private static function toolbar(array $f,array $authors):void{?><form class="aics-history-toolbar" method="get"><input type="hidden" name="page" value="aics-content-history"><input type="hidden" name="content_status" value="<?php echo esc_attr($f['content_status']);?>"><?php wp_nonce_field(self::AJAX_ACTION,self::NONCE);?><div class="aics-history-search"><label for="aics-content-search"><?php esc_html_e('Search','ai-content-studio');?></label><input id="aics-content-search" type="search" name="content_search" value="<?php echo esc_attr($f['content_search']);?>" maxlength="100" placeholder="<?php esc_attr_e('Search title, content, keyword, author or post ID…','ai-content-studio');?>"></div><div><label for="aics-date-from"><?php esc_html_e('Created From','ai-content-studio');?></label><input id="aics-date-from" type="date" name="date_from" value="<?php echo esc_attr($f['date_from']);?>"></div><div><label for="aics-date-to"><?php esc_html_e('Created To','ai-content-studio');?></label><input id="aics-date-to" type="date" name="date_to" value="<?php echo esc_attr($f['date_to']);?>"></div><div><label for="aics-content-author"><?php esc_html_e('Author','ai-content-studio');?></label><select id="aics-content-author" name="content_author"><option value="0"><?php esc_html_e('All Authors','ai-content-studio');?></option><?php foreach($authors as $author):$label=$author['display_name'];if($author['display_name']!==$author['user_login']){$duplicates=array_filter($authors,static fn($a)=>$a['display_name']===$author['display_name']);if(count($duplicates)>1){$label.=' ('.$author['user_login'].')';}}?><option value="<?php echo esc_attr((string)absint($author['ID']));?>" <?php selected($f['content_author'],absint($author['ID']));?>><?php echo esc_html($label);?></option><?php endforeach;?></select></div><div><label for="aics-content-source"><?php esc_html_e('Source','ai-content-studio');?></label><select id="aics-content-source" name="content_source"><option value="all"><?php esc_html_e('All Sources','ai-content-studio');?></option><option value="manual" <?php selected($f['content_source'],'manual');?>><?php esc_html_e('Manual Studio','ai-content-studio');?></option><option value="automation" <?php selected($f['content_source'],'automation');?>><?php esc_html_e('Automation','ai-content-studio');?></option></select></div><button type="button" class="button" data-aics-history-reset><?php esc_html_e('Reset Filters','ai-content-studio');?></button></form><?php }
	private static function tabs(array $f):void{$labels=array('all'=>__('All','ai-content-studio'),'draft'=>__('Draft','ai-content-studio'),'publish'=>__('Published','ai-content-studio'),'future'=>__('Scheduled','ai-content-studio'),'pending'=>__('Pending','ai-content-studio'));?><nav class="aics-history-tabs" aria-label="<?php esc_attr_e('Content status','ai-content-studio');?>"><?php foreach($labels as $status=>$label):$url=add_query_arg(array_filter(array('page'=>'aics-content-history','content_status'=>$status,'content_search'=>$f['content_search'],'content_author'=>$f['content_author']?:null,'date_from'=>$f['date_from']?:null,'date_to'=>$f['date_to']?:null,'content_source'=>'all'!==$f['content_source']?$f['content_source']:null)),admin_url('admin.php'));?><a href="<?php echo esc_url($url);?>" data-aics-history-status="<?php echo esc_attr($status);?>" <?php echo $status===$f['content_status']?'class="is-active" aria-current="page"':'';?>><?php echo esc_html($label);?></a><?php endforeach;?></nav><?php }
	private static function results(array $r):void{if($r['error']):?><div class="notice notice-error inline"><p><?php echo esc_html($r['error']);?></p></div><?php endif;?><div class="aics-history-summary"><strong><?php echo esc_html(sprintf(_n('%s content item','%s content items',$r['total'],'ai-content-studio'),number_format_i18n($r['total'])));?></strong><?php if($r['filters']['content_search']):?><span><?php echo esc_html(sprintf(__('Results for “%s”','ai-content-studio'),$r['filters']['content_search']));?></span><?php endif;?></div><?php if(!$r['items']):?><div class="aics-empty-state"><h3><?php echo esc_html(self::active($r['filters'])?__('No content matches the current search and filters.','ai-content-studio'):__('No WordPress content has been created by AI Content Studio yet.','ai-content-studio'));?></h3><?php if(self::active($r['filters'])):?><button type="button" class="button" data-aics-history-reset><?php esc_html_e('Reset Filters','ai-content-studio');?></button><?php else:?><a class="button button-primary aics-button-primary" href="<?php echo esc_url(admin_url('admin.php?page=aics-create-content'));?>"><?php esc_html_e('Create Your First Article','ai-content-studio');?></a><?php endif;?></div><?php else:?><div class="aics-history-table-wrap"><table class="widefat aics-history-table"><caption class="screen-reader-text"><?php esc_html_e('Generated WordPress content','ai-content-studio');?></caption><thead><tr><th><?php esc_html_e('Title','ai-content-studio');?></th><th><?php esc_html_e('Status','ai-content-studio');?></th><th><?php esc_html_e('Source','ai-content-studio');?></th><th><?php esc_html_e('Primary Keyword','ai-content-studio');?></th><th><?php esc_html_e('Author','ai-content-studio');?></th><th><?php esc_html_e('Created','ai-content-studio');?></th><th><?php esc_html_e('Actions','ai-content-studio');?></th></tr></thead><tbody><?php foreach($r['items'] as $item):self::row($item);endforeach;?></tbody></table></div><?php self::pagination($r);endif;}
	private static function row(array $i):void{$id=absint($i['ID']);$title=trim($i['post_title'])?:__('Untitled post','ai-content-studio');$excerpt=trim(wp_strip_all_tags($i['post_excerpt']?:$i['article_excerpt']));$excerpt=wp_trim_words($excerpt,18);$statuses=array('draft'=>'Draft','publish'=>'Published','future'=>'Scheduled','pending'=>'Pending');$sources=array('manual'=>'Manual Studio','automation'=>'Automation');$edit=current_user_can('edit_post',$id)?get_edit_post_link($id,''):'';$preview=current_user_can('read_post',$id)?get_preview_post_link($id):'';?><tr><td data-colname="<?php esc_attr_e('Title','ai-content-studio');?>"><a href="<?php echo esc_url($edit?:$preview);?>"><strong><?php echo esc_html($title);?></strong></a><?php if($excerpt):?><small><?php echo esc_html($excerpt);?></small><?php endif;?></td><td data-colname="<?php esc_attr_e('Status','ai-content-studio');?>"><span class="aics-history-status aics-history-status--<?php echo esc_attr($i['post_status']);?>"><?php echo esc_html($statuses[$i['post_status']]??__('Unknown','ai-content-studio'));?></span></td><td data-colname="<?php esc_attr_e('Source','ai-content-studio');?>"><?php echo esc_html($sources[$i['source_type']]??__('Legacy','ai-content-studio'));?></td><td data-colname="<?php esc_attr_e('Primary Keyword','ai-content-studio');?>"><?php echo esc_html($i['seo_focus_keyword']?:__('Not set','ai-content-studio'));?></td><td data-colname="<?php esc_attr_e('Author','ai-content-studio');?>"><?php echo esc_html($i['display_name']);?></td><td data-colname="<?php esc_attr_e('Created','ai-content-studio');?>"><?php echo esc_html(mysql2date(get_option('date_format').' '.get_option('time_format'),$i['post_date'],false));?></td><td data-colname="<?php esc_attr_e('Actions','ai-content-studio');?>"><?php if($edit):?><a href="<?php echo esc_url($edit);?>"><?php esc_html_e('Edit','ai-content-studio');?></a><?php endif;?><?php if('publish'===$i['post_status']&&current_user_can('read_post',$id)):?> <a href="<?php echo esc_url(get_permalink($id));?>"><?php esc_html_e('View','ai-content-studio');?></a><?php elseif($preview):?> <a href="<?php echo esc_url($preview);?>"><?php esc_html_e('Preview','ai-content-studio');?></a><?php endif;?></td></tr><?php }
	private static function pagination(array $r):void{if($r['pages']<2){return;}?><nav class="aics-history-pagination" aria-label="<?php esc_attr_e('Content History pagination','ai-content-studio');?>"><?php if($r['page']>1):?><a href="#" data-aics-history-page="<?php echo esc_attr((string)($r['page']-1));?>"><?php esc_html_e('Previous','ai-content-studio');?></a><?php endif;?><span><?php echo esc_html(sprintf(__('Page %1$d of %2$d','ai-content-studio'),$r['page'],$r['pages']));?></span><?php if($r['page']<$r['pages']):?><a href="#" data-aics-history-page="<?php echo esc_attr((string)($r['page']+1));?>"><?php esc_html_e('Next','ai-content-studio');?></a><?php endif;?></nav><?php }
	private static function active(array $f):bool{return ''!==$f['content_search']||'all'!==$f['content_status']||0!==$f['content_author']||''!==$f['date_from']||''!==$f['date_to']||'all'!==$f['content_source'];}
	private static function permission():void{if(!current_user_can(\AIContentStudio\Core\Permissions::manage())){wp_die(esc_html__('You do not have permission to access this page.','ai-content-studio'));}}
}
